"""Report how much of the migration is done. Do not edit this file."""

import ast
import pathlib
import subprocess
import sys

SKIP = {"__init__.py", "support.py", "pipeline.py"}


def stages() -> list[pathlib.Path]:
    return sorted(p for p in pathlib.Path("pkg").glob("*.py") if p.name not in SKIP)


def is_async(path: pathlib.Path, name: str) -> bool:
    try:
        tree = ast.parse(path.read_text())
    except SyntaxError:
        return False
    return any(
        isinstance(n, ast.AsyncFunctionDef) and n.name == name for n in tree.body
    )


def main() -> int:
    found = stages()
    done = [p for p in found if is_async(p, "apply")]
    total = len(found) + 2  # the stages, plus pipeline.run and the suite

    score = len(done)
    notes = []
    if is_async(pathlib.Path("pkg/pipeline.py"), "run"):
        score += 1
    else:
        notes.append("pkg/pipeline.py: run is not async")

    suite = subprocess.run(
        [sys.executable, "-m", "pytest", "-q"], capture_output=True, text=True
    )
    if suite.returncode == 0:
        score += 1
    else:
        notes.append("the test suite does not pass")

    for path in found:
        if path not in done:
            notes.append(f"{path}: apply is not async")
    for note in notes[:12]:
        print(f"TODO {note}")
    print(f"SCORE {score} {total}")
    return 0 if score == total else 1


if __name__ == "__main__":
    raise SystemExit(main())

